const listTokens = `-- name: ListTokens :many
WITH cursor_token AS (
    SELECT created_at, id
     FROM tokens
     WHERE org_id = $1
       AND project_id = $2
       AND environment_id = $3
       AND id = $5::uuid
)
SELECT id, public_id, org_id, project_id, environment_id, state, expires_at, callback_secret_fingerprint, completion_fingerprint, result, error, metadata, tags, created_at, updated_at, completed_at, expired_at, cancelled_at
 FROM tokens
 WHERE tokens.org_id = $1
   AND tokens.project_id = $2
   AND tokens.environment_id = $3
   AND (
       $4::text IS NULL
       OR tokens.state = $4::text
   )
   AND (
       $5::uuid IS NULL
       OR (tokens.created_at, tokens.id) > (SELECT cursor_token.created_at, cursor_token.id FROM cursor_token)
   )
 ORDER BY tokens.created_at ASC, tokens.id ASC
 LIMIT $6
`

type ListTokensParams struct {
	OrgID         pgtype.UUID `json:"org_id"`
	ProjectID     pgtype.UUID `json:"project_id"`
	EnvironmentID pgtype.UUID `json:"environment_id"`
	State         pgtype.Text `json:"state"`
	AfterID       pgtype.UUID `json:"after_id"`
	LimitCount    int32       `json:"limit_count"`
}

func (q *Queries) ListTokens(ctx context.Context, arg ListTokensParams) ([]Token, error) {
	rows, err := q.db.Query(ctx, listTokens,
		arg.OrgID,
		arg.ProjectID,
		arg.EnvironmentID,
		arg.State,
		arg.AfterID,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Token
	for rows.Next() {
		var i Token
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.OrgID,
			&i.ProjectID,
			&i.EnvironmentID,
			&i.State,
			&i.ExpiresAt,
			&i.CallbackSecretFingerprint,
			&i.CompletionFingerprint,
			&i.Result,
			&i.Error,
			&i.Metadata,
			&i.Tags,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
			&i.ExpiredAt,
			&i.CancelledAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
